scripts.copy-vendor:
node -e "
const fs = require('fs');
const { execSync } = require('child_process');
const src = process.cwd();
fs.rmSync('public/vendor', { recursive: true, force: true });
fs.mkdirSync('public/vendor/fontawesome-6/fontawesome-free', { recursive: true });
fs.mkdirSync('public/vendor/material-symbols', { recursive: true });
fs.mkdirSync('public/vendor/ruffle', { recursive: true });
execSync('cp -a ' + src + '/node_modules/@ruffle-rs/ruffle/. public/vendor/ruffle/', { stdio: 'inherit' });
execSync('cp -a ' + src + '/node_modules/@fortawesome/fontawesome-free/. public/vendor/fontawesome-6/fontawesome-free/', { stdio: 'inherit' });
execSync('cp -a ' + src + '/node_modules/material-symbols/. public/vendor/material-symbols/', { stdio: 'inherit' });
"
